// plugin/handlers/eventHandlers.ts
var import_obsidian10 = require("obsidian");
function registerEventHandlers(plugin) {
  plugin.registerEvent(
    plugin.app.vault.on("create", (file) => {
      if (!file.path.includes(plugin.settings.pathToWatch))
        return;
      if (file instanceof import_obsidian10.TFile) {
        plugin.processFileV2(file);
      }
    })
  );
  plugin.registerEvent(
    plugin.app.vault.on("rename", (file, oldPath) => {
      if (!file.path.includes(plugin.settings.pathToWatch))
        return;
      if (file instanceof import_obsidian10.TFile) {
        plugin.processFileV2(file, oldPath);
      }
    })
  );
}

// plugin/handlers/commandHandlers.ts
function registerCommandHandlers(plugin) {
  plugin.addCommand({
    id: "append-existing-tags",
    name: "Append existing tags",
    callback: async () => {
      const activeFile = plugin.app.workspace.getActiveFile();
      if (activeFile) {
        const fileContent = await plugin.getTextFromFile(activeFile);
        await plugin.appendSimilarTags(fileContent, activeFile);
      }
    }
  });
  plugin.addCommand({
    id: "show-assistant",
    name: "Show Assistant",
    callback: async () => {
      await plugin.showAssistantSidebar();
    }
  });
  plugin.addCommand({
    id: "add-to-inbox",
    name: "Put in inbox",
    callback: async () => {
      const activeFile = plugin.app.workspace.getActiveFile();
      if (activeFile) {
        await plugin.processFileV2(activeFile);
      }
    }
  });
  plugin.addCommand({
    id: "organize-text-file",
    name: "Organize text file",
    callback: async () => {
      const activeFile = plugin.app.workspace.getActiveFile();
      if (activeFile) {
        const fileContent = await plugin.getTextFromFile(activeFile);
        await plugin.organizeFile(activeFile, fileContent);
      }
    }
  });
}

// plugin/fileUtils.ts
var import_obsidian11 = require("obsidian");
async function ensureFolderExists(app2, folderPath) {
  if (!await app2.vault.adapter.exists(folderPath)) {
    await app2.vault.createFolder(folderPath);
  }
}
async function checkAndCreateFolders(app2, settings) {
  await ensureFolderExists(app2, settings.pathToWatch);
  await ensureFolderExists(app2, settings.defaultDestinationPath);
  await ensureFolderExists(app2, settings.attachmentsPath);
  await ensureFolderExists(app2, settings.logFolderPath);
  await ensureFolderExists(app2, settings.templatePaths);
  await ensureFolderExists(app2, settings.stagingFolder);
  await ensureFolderExists(app2, settings.backupFolderPath);
}
async function checkAndCreateTemplates(app2, settings) {
  const meetingNoteTemplatePath = `${settings.templatePaths}/meeting_note.md`;
  if (!await app2.vault.adapter.exists(meetingNoteTemplatePath)) {
    await app2.vault.create(
      meetingNoteTemplatePath,
      `## Meeting Details

- Date: {{date}} in format YYYY-MM-DD
- Participants: {{participants}}

## Audio Reference

![[{{audio_file}}]]

## Key Points

[Summarize the main points discussed in the meeting]

## Action Items

- [ ] Action item 1
  - [ ] Sub-action 1.1
  - [ ] Sub-action 1.2
- [ ] Action item 2
  - [ ] Sub-action 2.1
  - [ ] Sub-action 2.2

## Detailed Notes

[Add your meeting notes here, maintaining a hierarchical structure]

## Transcription

[Insert the full transcription below]

---

AI Instructions:
1. Merge the transcription into the content, focusing on key points and action items.
2. Summarize the main discussion points in the "Key Points" section, using bullet points for clarity.
3. Extract and list any action items or tasks in the "Action Items" section:
   - Use a hierarchical structure with main action items and sub-actions.
   - Maintain the original level of detail from the transcript.
   - Use indentation to show the relationship between main actions and sub-actions.
4. In the "Detailed Notes" section, create a hierarchical structure that reflects the meeting's flow:
   - Use headings (###, ####) for main topics.
   - Use bullet points and sub-bullets for detailed points under each topic.
   - Preserve the granularity of the discussion, including specific examples or minor points.
5. Preserve the reference to the original audio file.
6. Maintain the overall structure of the note, including all headers and sections.
7. Delete transcription. Mention that it can be accessed in the Original file`
    );
  }
}
async function moveFile(app2, file, humanReadableFileName, destinationFolder = "") {
  let destinationPath = `${destinationFolder}/${humanReadableFileName}.${file.extension}`;
  if (await app2.vault.adapter.exists((0, import_obsidian11.normalizePath)(destinationPath))) {
    const timestamp = Date.now();
    const timestampedFileName = `${humanReadableFileName}_${timestamp}`;
    destinationPath = `${destinationFolder}/${timestampedFileName}.${file.extension}`;
  }
  await ensureFolderExists(app2, destinationFolder);
  await app2.vault.rename(file, `${destinationPath}`);
  return file;
}
function isTFolder(file) {
  return file instanceof import_obsidian11.TFolder;
}
function getAllFolders(app2) {
  const allFiles = app2.vault.getAllLoadedFiles();
  const folderPaths = allFiles.filter((file) => isTFolder(file)).map((folder) => folder.path);
  return [...new Set(folderPaths)];
}

